module count_bulbasaurs(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] char_array [0:15],\n    input [3:0] valid_length,\n    output reg [3:0] result,\n    output reg done\n);\n    // State declarations\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] COUNT     = 3'd1;\n    localparam [2:0] CALC_MIN  = 3'd2;\n    localparam [2:0] DONE_ST   = 3'd3;\n    \n    reg [2:0] state;\n    reg [3:0] count_B, count_u, count_l, count_b, count_a, count_s, count_r;\n    reg [3:0] loop_index;\n    reg [4:0] cycle_counter;\n    reg [3:0] min_val;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 4'd0;\n            done <= 1'b0;\n            count_B <= 4'd0;\n            count_u <= 4'd0;\n            count_l <= 4'd0;\n            count_b <= 4'd0;\n            count_a <= 4'd0;\n            count_s <= 4'd0;\n            count_r <= 4'd0;\n            loop_index <= 4'd0;\n            cycle_counter <= 5'd0;\n            min_val <= 4'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_counter <= 5'd0;\n                    if (start) begin\n                        count_B <= 4'd0;\n                        count_u <= 4'd0;\n                        count_l <= 4'd0;\n                        count_b <= 4'd0;\n                        count_a <= 4'd0;\n                        count_s <= 4'd0;\n                        count_r <= 4'd0;\n                        loop_index <= 4'd0;\n                        state <= COUNT;\n                    end\n                end\n                \n                COUNT: begin\n                    cycle_counter <= cycle_counter + 5'd1;\n                    \n                    if (loop_index < valid_length) begin\n                        case (char_array[loop_index])\n                            8'd66:   count_B <= count_B + 4'd1;  // 'B'\n                            8'd117:  count_u <= count_u + 4'd1;  // 'u'\n                            8'd108:  count_l <= count_l + 4'd1;  // 'l'\n                            8'd98:   count_b <= count_b + 4'd1;  // 'b'\n                            8'd97:   count_a <= count_a + 4'd1;  // 'a'\n                            8'd115:  count_s <= count_s + 4'd1;  // 's'\n                            8'd114:  count_r <= count_r + 4'd1;  // 'r'\n                            default: ;\n                        endcase\n                        loop_index <= loop_index + 4'd1;\n                    end else begin\n                        state <= CALC_MIN;\n                    end\n                    \n                    if (cycle_counter >= 5'd18) begin\n                        state <= CALC_MIN;\n                    end\n                end\n                \n                CALC_MIN: begin\n                    // Calculate minimum value\n                    min_val <= count_B;\n                    if ((count_u >> 1) < min_val) min_val <= count_u >> 1;\n                    if (count_l < min_val) min_val <= count_l;\n                    if (count_b < min_val) min_val <= count_b;\n                    if ((count_a >> 1) < min_val) min_val <= count_a >> 1;\n                    if (count_s < min_val) min_val <= count_s;\n                    if (count_r < min_val) min_val <= count_r;\n                    \n                    state <= DONE_ST;\n                end\n                \n                DONE_ST: begin\n                    result <= min_val;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule